/*
 * Agent trust (agent_trust.h) against grants, manifests and keys the hub's
 * own Go encoders signed (trust_fixtures.h, regenerated by
 * hub/pkg/response/trust_fixtures_test.go). Builds with gcc (POSIX file
 * backend) and with mingw (Win32 backend); both must pass.
 *
 * The rule under test: an action outside the manifest, or without a valid
 * grant signed by the right key for this endpoint and kind, is refused by the
 * agent itself, whatever the hub sends.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <time.h>
#ifdef _WIN32
#include <winsock2.h>
#include <windows.h>
#include <direct.h>
#else
#include <unistd.h>
#include <sys/stat.h>
#endif

#include "../include/agent_trust.h"
#include "trust_fixtures.h"
#include "routine_fixtures.h"
#ifndef _WIN32
#include "../include/release_verify_posix.h"
#endif

static int failures = 0;

static void expect(const char* name, bool ok) {
    if (!ok) {
        printf("  [-] %s\n", name);
        failures++;
    } else {
        printf("  [+] %s\n", name);
    }
}

static char g_dir[200];

static void make_dir(void) {
#ifdef _WIN32
    char tmp[MAX_PATH];
    GetTempPathA(sizeof(tmp), tmp);
    snprintf(g_dir, sizeof(g_dir), "%sominull-trust-%lu", tmp, (unsigned long)GetCurrentProcessId());
    _mkdir(g_dir);
#else
    snprintf(g_dir, sizeof(g_dir), "/tmp/ominull-trust-XXXXXX");
    if (!mkdtemp(g_dir)) {
        perror("mkdtemp");
        exit(2);
    }
#endif
}

static void remove_dir(void) {
    const char* files[] = {"response.pub", "auto_isolate.pub", "policy.pub", "trust.pin", "trust.epoch", "manifest.state", "manifest.floor",
                           "capability.ceiling", "enforcement.state", "host_authority.json", "host_auto_allow.json",
                           "routine.pin", "routine.epoch"};
    char path[400];
    for (size_t i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
        snprintf(path, sizeof(path), "%s" TRUST_SEP "%s", g_dir, files[i]);
        remove(path);
    }
#ifdef _WIN32
    _rmdir(g_dir);
#else
    rmdir(g_dir);
#endif
}

static TrustContext T;
static char resp[65536];

#ifdef _WIN32
/* The Windows verifier is CNG with the compiled-in release key (updater.c);
 * here a table of the pairs the fixture release key signed stands in. */
static bool fake_verify(const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    static const char* sigs[] = {FX_TB_SIG, FX_TB_SIG_OTHER_KEYS, FX_TB_SIG_OLD, FX_TB_SIG_TENANT, FX_TB_SIG_NEXT};
    const char* msgs[] = {FX_TB_STATEMENT, FX_TB_STATEMENT_OTHER_KEYS, FX_TB_STATEMENT_OLD, FX_TB_STATEMENT_TENANT, FX_TB_STATEMENT_NEXT};
    for (int i = 0; i < 5; i++) {
        uint8_t want[160];
        size_t wl = Response_Base64Decode(sigs[i], strlen(sigs[i]), want, sizeof(want));
        if (len == strlen(msgs[i]) && memcmp(msg, msgs[i], len) == 0 && derlen == wl && memcmp(der, want, wl) == 0) return true;
    }
    return false;
}
#endif

static void init(void) {
    Trust_Init(&T, FX_ENDPOINT, g_dir, g_dir, false);
#ifdef _WIN32
    T.verify_release = fake_verify;
#else
    g_ReleaseVerifyPem = FX_TB_PUB_PEM;
    snprintf(g_ReleaseVerifyDir, sizeof(g_ReleaseVerifyDir), "%s", g_dir);
    T.verify_release = ReleaseVerifyPosix;
#endif
}

/* A trust offer as the hub sends it: the keys plus the bundle signature. */
static char offer_buf[2][1024];
static const char* offer(int slot, const char* keys, const char* sig) {
    size_t n = strlen(keys);
    if (!sig) return keys;
    snprintf(offer_buf[slot], sizeof(offer_buf[slot]), "%.*s,\"bundle_sig\":\"%s\"}", (int)(n - 1), keys, sig);
    return offer_buf[slot];
}

/* A heartbeat answer as the hub writes it, with optional parts. */
static void beat(int64_t now, const char* keys, const char* manifest, const char* const* grants, int ngrants) {
    int off = snprintf(resp, sizeof(resp), "{\"status\":\"ok\",\"quarantined_peers\":[\"10.0.0.250\"],\"is_isolated\":true,"
                                           "\"isolation_allow_ips\":[\"10.0.0.251\"],\"isolation_baseline\":[]");
    if (keys) off += snprintf(resp + off, sizeof(resp) - off, ",\"trust\":%s", keys);
    if (manifest) off += snprintf(resp + off, sizeof(resp) - off, ",\"capability_manifest\":%s", manifest);
    if (ngrants) {
        off += snprintf(resp + off, sizeof(resp) - off, ",\"enforcement_grants\":[");
        for (int i = 0; i < ngrants; i++) off += snprintf(resp + off, sizeof(resp) - off, "%s%s", i ? "," : "", grants[i]);
        off += snprintf(resp + off, sizeof(resp) - off, "]");
    }
    /* Marks a hub might send are ignored: bootstrap marks come from the
     * agent's own clock. */
    off += snprintf(resp + off, sizeof(resp) - off, ",\"enforcement_marks\":{\"iso\":9999999999,\"mesh\":9999999999}}");
    Trust_ProcessHeartbeat(&T, resp, strlen(resp), now);
}

static void one(int64_t now, const char* grant) {
    const char* g[1] = {grant};
    beat(now, NULL, NULL, g, 1);
}

static bool refused_with(const char* needle) { return strstr(T.refused, needle) != NULL; }

static void test_versions(void) {
    printf("[*] version monotonicity\n");
    expect("1.8.56 > 1.8.55 admissible", Trust_UpdateVersionAdmissible("1.8.56", "1.8.55"));
    expect("1.10.0 > 1.9.9 admissible (numeric, not lexical)", Trust_UpdateVersionAdmissible("1.10.0", "1.9.9"));
    expect("same version refused", !Trust_UpdateVersionAdmissible("1.8.55", "1.8.55"));
    expect("downgrade refused", !Trust_UpdateVersionAdmissible("1.8.54", "1.8.55"));
    expect("1.8 == 1.8.0 refused", !Trust_UpdateVersionAdmissible("1.8", "1.8.0"));
    expect("malformed refused", !Trust_UpdateVersionAdmissible("1.8.x", "1.8.0"));
    expect("empty refused", !Trust_UpdateVersionAdmissible("", "1.8.0"));
    expect("huge part refused", !Trust_UpdateVersionAdmissible("1.9999999999", "1.0"));
    expect("leading text refused", !Trust_UpdateVersionAdmissible("v2.0.0", "1.0.0"));
    char st[512];
    Trust_ReleaseStatement("ominull-agent_9.9.9_amd64.deb", "9.9.9",
                           "abababababababababababababababababababababababababababababababab", st, sizeof(st));
    expect("release statement matches the Go form byte for byte", strcmp(st, FX_RELEASE_STATEMENT) == 0);
}

static void test_ip(void) {
    printf("[*] address literals\n");
    expect("v4 ok", Trust_IsIPLiteral("10.0.0.9"));
    expect("v4 out of range refused", !Trust_IsIPLiteral("10.0.0.256"));
    expect("v4 short refused", !Trust_IsIPLiteral("10.0.0"));
    expect("v6 ok", Trust_IsIPLiteral("fd00::1"));
    expect("v6 full ok", Trust_IsIPLiteral("1:2:3:4:5:6:7:8"));
    expect("v6 double :: refused", !Trust_IsIPLiteral("1::2::3"));
    expect("v6 long group refused", !Trust_IsIPLiteral("12345::1"));
    expect("cidr refused", !Trust_IsIPLiteral("0.0.0.0/0"));
    expect("name refused", !Trust_IsIPLiteral("example"));
    expect("allow entry: address", Trust_IsAllowEntry("10.0.0.9") && Trust_IsAllowEntry("fd00::1"));
    expect("allow entry: v4 range", Trust_IsAllowEntry("10.0.8.0/22") && Trust_IsAllowEntry("10.0.0.0/8") && Trust_IsAllowEntry("10.0.0.9/32"));
    expect("allow entry: v6 range", Trust_IsAllowEntry("fd00:10::/48") && Trust_IsAllowEntry("fd00::/32") && Trust_IsAllowEntry("fd00::1/128") &&
                                        Trust_IsAllowEntry("2001:db8::/32") && Trust_IsAllowEntry("2a00:1450::/32"));
    expect("allow entry: link-local and translation ranges refused", !Trust_IsAllowEntry("fe80::/64") && !Trust_IsAllowEntry("64:ff9b::/96") &&
                                                                       !Trust_IsAllowEntry("2001::/32") && !Trust_IsAllowEntry("2001:0:1::/48") &&
                                                                       !Trust_IsAllowEntry("2002::/16") && !Trust_IsAllowEntry("2002:a00::/32") &&
                                                                       !Trust_IsAllowEntry("::ffff:0:0/96") && !Trust_IsAllowEntry("ff02::/32"));
    expect("allow entry: too wide refused", !Trust_IsAllowEntry("0.0.0.0/0") && !Trust_IsAllowEntry("10.0.0.0/7") && !Trust_IsAllowEntry("fd00::/31") &&
                                               !Trust_IsAllowEntry("::/0"));
    expect("allow entry: malformed refused", !Trust_IsAllowEntry("10.0.0.0/") && !Trust_IsAllowEntry("10.0.0.0/33") && !Trust_IsAllowEntry("fd00::/129") &&
                                                 !Trust_IsAllowEntry("10.0.0.0/024") && !Trust_IsAllowEntry("10.0.0.0/2x") &&
                                                 !Trust_IsAllowEntry("/24") && !Trust_IsAllowEntry("10.0.0/24") && !Trust_IsAllowEntry("10.0.0.0/24/1"));
    printf("[*] threat indicators only for public addresses\n");
    expect("public v4", Trust_PublicAddress("8.8.8.8") && Trust_PublicAddress("1.2.3.4"));
    const char* local[] = {"10.0.0.1", "127.0.0.53", "192.168.1.1", "172.16.0.1", "172.31.255.255", "169.254.1.1",
                           "100.64.0.1", "224.0.0.251", "255.255.255.255", "0.0.0.0", "::1", "::", "fe80::1",
                           "fd00::1", "ff02::1", "2001:db8::1", "::ffff:1:2", NULL};
    for (int i = 0; local[i]; i++) {
        char what[96];
        snprintf(what, sizeof(what), "%s is not dropped", local[i]);
        expect(what, !Trust_PublicAddress(local[i]));
    }
    expect("public v6", Trust_PublicAddress("2606:4700::1111") && Trust_PublicAddress("2a00:1450:4001::1"));
    expect("172.32 is public", Trust_PublicAddress("172.32.0.1"));
}

static void test_pinning_and_bootstrap(int64_t now) {
    printf("[*] key pinning and one-time bootstrap\n");
    init();
    expect("fresh host has no keys", !T.have_key[0] && !T.have_key[1] && !T.have_key[2]);
    expect("fresh host has no state file", !T.state.exists);
    int64_t boot = FX_T0 - 4 * 86400;   /* the upgrade happened before every fixture grant */
    beat(boot, FX_KEYS_JSON, NULL, NULL, 0);
    expect("an unsigned trust offer pins nothing", !T.have_key[0] && !T.have_key[1] && !T.have_key[2] && refused_with("not signed"));
    expect("bootstrap marks come from this host's clock, not the hub", T.state.iso_seen == boot - 60 && T.state.mesh_seen == boot - 60);
    beat(boot, offer(0, FX_KEYS_JSON, FX_TB_SIG_WRONG_SIGNER), NULL, NULL, 0);
    expect("a bundle signed by another key pins nothing", !T.have_key[0] && refused_with("does not verify"));
    beat(boot, offer(0, FX_KEYS_OTHER_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("a genuine signature over other keys pins nothing", !T.have_key[0]);
    beat(boot, offer(0, FX_KEYS_TENANT_JSON, FX_TB_SIG_TENANT), NULL, NULL, 0);
    expect("another tenant's genuine bundle pins nothing", !T.have_key[0] && refused_with("another tenant"));
    beat(boot, offer(0, FX_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("three keys pinned from the release-signed bundle", T.have_key[0] && T.have_key[1] && T.have_key[2]);
    expect("tenant and epoch pinned with them", strcmp(T.tenant, "default") == 0 && T.epoch == 2 && T.epoch_floor == 2);
    expect("bootstrap adopted the hub's isolation once", T.state.isolated && strcmp(T.state.source, "bootstrap") == 0);
    expect("bootstrap adopted allow list", T.state.allowCount == 1 && strcmp(T.state.allow[0], "10.0.0.251") == 0);
    expect("bootstrap adopted mesh peers", T.state.meshCount == 1 && T.state.mesh[0].on);
    expect("bootstrap isolation releases on dead-man as before", Trust_DeadmanBeats(&T, 100, 3000) == 100);

    beat(now, offer(1, FX_KEYS_OTHER_KEYS_JSON, FX_TB_SIG_OTHER_KEYS), NULL, NULL, 0);
    expect("a different, release-signed key set does not replace the pins", T.mismatch[0] && T.mismatch[1] && T.mismatch[2]);
    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report says mismatch", strstr(report, "\"keys\":\"mismatch\"") != NULL);
    init();
    uint8_t want[32];
    Trust_HexKey(FX_RESPONSE_PUB, want);
    expect("pinned response key survives the offer", T.have_key[0] && memcmp(T.keys[0], want, 32) == 0);
    expect("state persisted across restart", T.state.exists && T.state.isolated);
}

static void test_manifest(int64_t now) {
    printf("[*] capability manifest\n");
    init();
    expect("no manifest: only updates allowed", Trust_Allows(&T, "agent_update") && !Trust_Allows(&T, "terminal_session") &&
                                                 !Trust_Allows(&T, "isolation_change"));
    beat(now, NULL, FX_M_FORGED_3, NULL, 0);
    expect("manifest signed by another key refused", !T.manifest.have && refused_with("does not verify"));
    beat(now, NULL, FX_M_OTHER_EP_3, NULL, 0);
    expect("manifest for another endpoint refused", !T.manifest.have);
    beat(now, NULL, FX_M_RESPOND_1, NULL, 0);
    expect("respond manifest accepted", T.manifest.have && T.manifest.seq == 1 && strcmp(T.manifest.profile, "respond") == 0);
    expect("respond allows terminal, collect, isolate, mesh", Trust_Allows(&T, "terminal_session") && Trust_Allows(&T, "forensic_collection") &&
                                                          Trust_Allows(&T, "isolation_change") && Trust_Allows(&T, "mesh_quarantine"));
    expect("respond does not allow scripts", !Trust_Allows(&T, "script_exec"));
    beat(now, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
    expect("same-seq different manifest refused (no replay of a sibling)", strcmp(T.manifest.profile, "respond") == 0);
    init();
    expect("manifest persisted across restart", T.manifest.have && T.manifest.seq == 1);

    printf("[*] local capability ceiling\n");
    expect("ceiling set to monitor", Trust_SetCeiling(&T, "monitor"));
    init();
    expect("a monitor ceiling caps a respond manifest", !Trust_Allows(&T, "isolation_change") && !Trust_Allows(&T, "terminal_session") &&
                                                       !Trust_Allows(&T, "mesh_quarantine") && Trust_Allows(&T, "agent_update"));
    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report carries the ceiling", strstr(report, "\"ceiling\":\"monitor\"") != NULL);
    expect("unknown ceiling refused", !Trust_SetCeiling(&T, "everything"));
    expect("ceiling removed", Trust_SetCeiling(&T, "none"));
    init();
    expect("without a ceiling the manifest decides", Trust_Allows(&T, "terminal_session"));
}

static void test_grants(int64_t now) {
    printf("[*] enforcement grants\n");
    init();
    /* Start from a released host so each step is visible. */
    Trust_LocalRelease(&T);
    expect("local release clears isolation", !T.state.isolated && strcmp(T.state.source, "local") == 0);

    one(now, FX_G_ISO_EXPIRED);
    expect("expired grant refused", !T.state.isolated && refused_with("expired"));
    one(now, FX_G_ISO_FORGED);
    expect("forged isolation refused", !T.state.isolated && refused_with("does not verify"));
    expect("forged far-future grant does not move the watermark", T.state.iso_seen < FX_T0);
    one(now, FX_G_ISO_OTHER_EP);
    expect("grant for another endpoint refused", !T.state.isolated && refused_with("another endpoint"));
    one(now, FX_G_ISO_TAMPERED);
    expect("payload changed after signing refused", !T.state.isolated && refused_with("digest"));
    one(now, FX_G_ISO_DUP_ROUTE);
    expect("duplicate route keys refused", !T.state.isolated);
    one(now, FX_G_ISO_CASE_ROUTE);
    expect("case-variant keys refused", !T.state.isolated);
    one(now, FX_G_ISO_ESC_ROUTE);
    expect("escaped key refused", !T.state.isolated);
    one(now, FX_G_MESH_KIND_ISO);
    expect("mesh-kind grant over an isolation route refused", !T.state.isolated && T.state.meshCount <= 1);
    one(now, FX_G_AUTO_SIGNED_OWNER);
    expect("auto kind signed by the owner key refused", !T.state.isolated);
    one(now, FX_G_OWNER_SIGNED_AUTO);
    expect("owner kind signed by the auto key refused", !T.state.isolated);

    one(now, FX_G_ISO_OTHER_EP_LATE);
    expect("a newer genuine grant for another endpoint does not move this host's mark", T.state.iso_seen < FX_T0 + 10 &&
                                                                                        refused_with("another endpoint"));
    one(now, FX_G_ISO);
    expect("owner isolation applied", T.state.isolated && strcmp(T.state.source, "owner") == 0);
    expect("owner allow list applied", T.state.allowCount == 1 && strcmp(T.state.allow[0], "10.0.0.9") == 0);
    expect("owner isolation holds 12 h on the dead-man (3 s beats)", Trust_DeadmanBeats(&T, 100, 3000) == 14400);
    expect("owner isolation holds 12 h on the dead-man (2.5 s beats)", Trust_DeadmanBeats(&T, 120, 2500) == 17280);

    one(now, FX_G_AUTO_RELEASE);
    expect("auto-isolation key cannot release", T.state.isolated && refused_with("other than isolating"));
    one(now, FX_G_REL);
    expect("owner release applied", !T.state.isolated && strcmp(T.state.source, "none") == 0);
    one(now, FX_G_ISO);
    expect("replayed older isolation ignored", !T.state.isolated);
    one(now, FX_G_AUTO);
    expect("detector isolation applied", T.state.isolated && strcmp(T.state.source, "auto") == 0 && T.state.allowCount == 0);
    expect("detector isolation keeps the 5 min dead-man", Trust_DeadmanBeats(&T, 100, 3000) == 100);

    one(now, FX_G_MESH_ON);
    bool on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("mesh quarantine applied", on);
    one(now, FX_G_MESH_OFF);
    on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("mesh quarantine lifted", !on);
    one(now, FX_G_MESH_ON);
    on = false;
    for (int i = 0; i < T.state.meshCount; i++) if (strcmp(T.state.mesh[i].ip, "10.0.0.66") == 0 && T.state.mesh[i].on) on = true;
    expect("replayed quarantine ignored", !on);

    one(now, FX_G_REL_AUTO);
    expect("owner releases the detector's isolation", !T.state.isolated);

    beat(now, NULL, FX_M_MONITOR_2, NULL, 0);
    expect("narrower manifest accepted", strcmp(T.manifest.profile, "monitor") == 0);
    one(now, FX_G_BULK_ISO);
    expect("isolation refused outside the manifest", !T.state.isolated && refused_with("manifest"));
    beat(now, NULL, FX_M_RESPOND_1, NULL, 0);
    expect("older manifest refused", strcmp(T.manifest.profile, "monitor") == 0 && refused_with("older"));
    beat(now, NULL, FX_M_RESPOND_3, NULL, 0);
    one(now, FX_G_ISO_3);
    expect("isolation accepted again under a newer respond manifest", T.state.isolated);
    beat(now, NULL, FX_M_RESPOND_3, NULL, 0);
    one(now, FX_G_FUTURE_FORGED);
    expect("forged release refused", T.state.isolated);

    init();
    expect("authorized state survives a restart", T.state.isolated && strcmp(T.state.source, "owner") == 0);

    one(now, FX_G_ISO_RULES);
    expect("an isolation's bound exceptions are applied with it", T.state.isolated && T.state.ruleCount == 2 &&
                                                                     strcmp(T.state.rules[0].destination, "192.0.2.53") == 0 &&
                                                                     T.state.rules[1].port == 67);
    init();
    expect("bound exceptions survive a restart", T.state.ruleCount == 2 && strcmp(T.state.rules[0].service, "dns") == 0);
    one(now, FX_G_ISO_RULES_BAD);
    expect("an exception that is not an address refuses the isolation", T.state.ruleCount == 2 && refused_with("exceptions"));
    one(now, FX_G_ISO_RULES_TWICE);
    expect("a host named in two exception sets is refused", T.state.ruleCount == 2 && refused_with("twice"));
    one(now, FX_G_REL_RULES);
    expect("release clears the exceptions", !T.state.isolated && T.state.ruleCount == 0);

    one(now, FX_G_ISO_CIDR_WIDE);
    expect("an allow range wider than /8 refuses the isolation", !T.state.isolated && refused_with("too wide"));
    one(now, FX_G_ISO_CIDR);
    expect("allow ranges are applied", T.state.isolated && T.state.allowCount == 3 && strcmp(T.state.allow[1], "10.0.8.0/22") == 0 &&
                                           strcmp(T.state.allow[2], "fd00:10::/48") == 0);
    init();
    expect("allow ranges survive a restart", T.state.isolated && T.state.allowCount == 3 && strcmp(T.state.allow[2], "fd00:10::/48") == 0);
    one(now, FX_G_REL_CIDR);
    expect("release clears the allow ranges", !T.state.isolated && T.state.allowCount == 0);
}

static void test_monitor_release(int64_t now) {
    printf("[*] narrowing never frees a contained host\n");
    make_dir();
    init();
    beat(FX_T0 - 4 * 86400, offer(0, FX_KEYS_JSON, FX_TB_SIG), FX_M_RESPOND_1, NULL, 0);
    Trust_LocalRelease(&T);
    one(now, FX_G_ISO);
    expect("isolated under respond", Trust_EffectiveIsolated(&T));
    beat(now, NULL, FX_M_MONITOR_2, NULL, 0);
    expect("still isolated after the manifest narrows", Trust_EffectiveIsolated(&T));
    one(now, FX_G_REL);
    expect("release accepted under a monitor manifest", !Trust_EffectiveIsolated(&T));
    remove_dir();
}

static void test_offers_and_updates(int64_t now) {
    printf("[*] response offers and agent updates\n");
    make_dir();
    init();
    beat(FX_T0 - 4 * 86400, offer(0, FX_KEYS_JSON, FX_TB_SIG), FX_M_RESPOND_1, NULL, 0);
    ResponseGrant g;
    memset(&g, 0, sizeof(g));
    snprintf(g.action_kind, sizeof(g.action_kind), "isolation_change");
    expect("offer kind must equal the grant's kind", Trust_OfferRefusal(&T, "terminal_session", &g) != NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "terminal_session");
    snprintf(g.tenant_id, sizeof(g.tenant_id), "other");
    expect("an offer for another tenant is refused", Trust_OfferRefusal(&T, "terminal_session", &g) != NULL);
    snprintf(g.tenant_id, sizeof(g.tenant_id), "default");
    expect("terminal allowed under respond", Trust_OfferRefusal(&T, "terminal_session", &g) == NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "script_exec");
    expect("script refused under respond", Trust_OfferRefusal(&T, "script_exec", &g) != NULL);
    snprintf(g.action_kind, sizeof(g.action_kind), "agent_update");
    expect("update grant is not a response job", Trust_OfferRefusal(&T, "agent_update", &g) != NULL);

    char r[16384];
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE);
    expect("owner-approved update accepted", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) == NULL);
    expect("update grant for another version refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.8", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"}}");
    expect("update without a grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_FORGED);
    expect("forged update grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_OTHER_EP);
    expect("update grant for another endpoint refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE_AS_ISO);
    expect("update payload under an isolation grant refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now) != NULL);
    snprintf(r, sizeof(r), "{\"agent_update\":{\"version\":\"9.9.9\"},\"agent_update_grant\":%s}", FX_G_UPDATE);
    expect("update grant expired after 7 days refused", Trust_UpdateAuthorized(&T, r, strlen(r), "9.9.9", now + 8 * 86400) != NULL);
    one(now, FX_G_TERMINAL_AS_ISO);
    expect("terminal payload under an isolation grant refused", refused_with("route"));

    char report[768];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report: keys pinned, manifest 1, respond", strstr(report, "\"keys\":\"pinned\"") && strstr(report, "\"manifest_seq\":1") &&
                                                          strstr(report, "\"profile\":\"respond\""));
    expect("report carries no key material", strstr(report, FX_RESPONSE_PUB) == NULL);

    char pinpath[400], savedpin[600] = "";
    snprintf(pinpath, sizeof(pinpath), "%s" TRUST_SEP "trust.pin", g_dir);
    Trust_ReadSmallFile(&T, pinpath, savedpin, sizeof(savedpin));
    expect("explicit re-pin removes the pinned bundle", Trust_Repin(&T) == 1);
    /* Interrupted after the floor was written, before the pin went: the
     * retry finishes without climbing past the next epoch. */
    Trust_WriteFile(&T, pinpath, savedpin, false);
    init();
    expect("a retried re-pin removes the pin again", Trust_Repin(&T) == 1);
    init();
    expect("after re-pin no key is trusted", !T.have_key[0] && !T.have_key[1] && !T.have_key[2]);
    expect("the re-pin raises the epoch floor past the revoked bundle", T.epoch_floor == 3);
    expect("a second re-pin with nothing pinned does not climb", Trust_Repin(&T) == 0);
    init();
    expect("the floor stays one above the revoked bundle", T.epoch_floor == 3);
    beat(FX_T0, offer(0, FX_KEYS_OLD_JSON, FX_TB_SIG_OLD), NULL, NULL, 0);
    expect("an older, genuinely signed bundle is not pinned again", !T.have_key[0] && refused_with("older"));
    beat(FX_T0, offer(0, FX_KEYS_JSON, FX_TB_SIG), NULL, NULL, 0);
    expect("the revoked bundle (same epoch) is not pinned again after a re-pin", !T.have_key[0] && refused_with("older"));
    beat(FX_T0, offer(0, FX_KEYS_NEXT_JSON, FX_TB_SIG_NEXT), NULL, NULL, 0);
    expect("the next epoch's bundle pins", T.have_key[0] && T.epoch == 3);
    beat(FX_T0, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
    expect("after a re-pin an older, wider manifest is not taken", !(T.manifest.have && strcmp(T.manifest.profile, "engagement") == 0) &&
                                                                 refused_with("older"));
    {
        /* The floor follows the policy key, not the bundle epoch: with the
         * manifest file gone and the epoch moved (another key or a raised
         * authority floor), an older manifest under the same key is refused. */
        int64_t seq = T.manifest.seq;
        char path[400], saved[1024];
        Trust_ManifestJSON(&T.manifest, saved, sizeof(saved));
        snprintf(path, sizeof(path), "%s" TRUST_SEP "manifest.state", g_dir);
        remove(path);
        init();
        expect("the floor survives without the manifest file", T.mfloorCount == 1 && T.mfloor[0].seq == seq && !T.manifest.have);
        T.epoch = 99;
        beat(FX_T0, NULL, FX_M_ENGAGEMENT_1, NULL, 0);
        expect("an older manifest under the same policy key is refused at another epoch",
               !T.manifest.have && refused_with("already taken under this policy key"));
        /* A floor behind the stored manifest (stop between the two writes) is
         * raised from the manifest at start. */
        Trust_WriteFile(&T, path, saved, false);
        snprintf(path, sizeof(path), "%s" TRUST_SEP "manifest.floor", g_dir);
        remove(path);
        init();
        expect("the floor is raised from the stored manifest", T.manifest.have && T.mfloorCount == 1 && T.mfloor[0].seq == T.manifest.seq);
        beat(FX_T0, NULL, NULL, NULL, 0);
        expect("the raised floor is made durable on the next beat", !T.mfloor_dirty && Trust_PathExists(path));
        /* Recovered at start, then a re-pin straight away (no beat): the
         * floor is written before the pin goes. */
        remove(path);
        init();
        expect("floor recovered in memory only", T.mfloor_dirty && !Trust_PathExists(path));
        char pinpath2[400], keep[600] = "", ep[400], keepep[64] = "";
        snprintf(pinpath2, sizeof(pinpath2), "%s" TRUST_SEP "trust.pin", g_dir);
        snprintf(ep, sizeof(ep), "%s" TRUST_SEP "trust.epoch", g_dir);
        Trust_ReadSmallFile(&T, pinpath2, keep, sizeof(keep));
        Trust_ReadSmallFile(&T, ep, keepep, sizeof(keepep));
        expect("a re-pin with a recovered floor succeeds", Trust_Repin(&T) == 1);
        init();
        expect("and the floor is on disk after it", Trust_PathExists(path) && T.mfloorCount == 1 && T.mfloor[0].seq == seq);
        Trust_WriteFile(&T, pinpath2, keep, false);   /* put the pin back for the checks below */
        Trust_WriteFile(&T, ep, keepep, false);
        init();
        /* A policy key that comes back (A, B, A) keeps its own floor. */
        uint8_t a[32];
        memcpy(a, T.keys[TRUST_KEY_POLICY], 32);
        expect("policy key A floor written", Trust_RaiseManifestFloor(&T, seq));
        memset(T.keys[TRUST_KEY_POLICY], 0x42, 32);
        expect("policy key B floor written", Trust_RaiseManifestFloor(&T, 1));
        init();
        expect("both policy keys keep a floor", T.mfloorCount == 2);
        memcpy(T.keys[TRUST_KEY_POLICY], a, 32);
        expect("key A's floor is still in force after B", Trust_ManifestFloored(&T, seq) && !Trust_ManifestFloored(&T, seq + 1));
    }
    remove_dir();
}

/* ---- host authority (docs/HOST_AUTHORITY.md) ---- */

static uint8_t hk_pub[2][32], hk_sec[2][64];
static char hk_id[2][65];

static void host_keys_setup(void) {
    for (int i = 0; i < 2; i++) {
        uint8_t seed[32], fp[32];
        memset(seed, 0x30 + i, sizeof(seed));
        Ed25519_CreateKeypairFromSeed(hk_pub[i], hk_sec[i], seed);
        Response_SHA256_Sum(hk_pub[i], 32, fp);
        Response_BytesToHex(fp, 32, hk_id[i]);
    }
}

static void write_host_file(const char* leaf, const char* body) {
    char path[400];
    snprintf(path, sizeof(path), "%s" TRUST_SEP "%s", g_dir, leaf);
    FILE* f = fopen(path, "wb");
    if (f) {
        fputs(body, f);
        fclose(f);
    }
}

static void remove_host_file(const char* leaf) {
    char path[400];
    snprintf(path, sizeof(path), "%s" TRUST_SEP "%s", g_dir, leaf);
    remove(path);
}

static char hk_payload[2048];
static char hk_digest[65];

/* A script_exec payload as the hub encodes it, for the source given. */
static void host_payload(const char* source, const char* mode) {
    uint8_t h[32];
    char sd[65];
    Response_SHA256_Sum((const uint8_t*)source, strlen(source), h);
    Response_BytesToHex(h, 32, sd);
    snprintf(hk_payload, sizeof(hk_payload),
             "{\"script_id\":\"scrub\",\"script_version\":1,\"script_digest\":\"%s\",\"interpreter\":\"/bin/sh\",\"source\":\"%s\","
             "\"parameters\":{\"mode\":\"%s\"},\"timeout_seconds\":60,\"max_output_bytes\":4096}",
             sd, source, mode);
    snprintf(hk_digest, sizeof(hk_digest), "%s", sd);
}

/* A V3 grant over hk_payload signed by host key k. */
static void host_grant(ResponseGrant* g, int k, int version, const char* job, const char* op) {
    memset(g, 0, sizeof(*g));
    int64_t now = (int64_t)time(NULL);
    uint8_t h[32];
    g->version = (uint32_t)version;
    snprintf(g->grant_id, sizeof(g->grant_id), "ns-1");
    snprintf(g->tenant_id, sizeof(g->tenant_id), "default");
    snprintf(g->endpoint_id, sizeof(g->endpoint_id), FX_ENDPOINT);
    snprintf(g->action_kind, sizeof(g->action_kind), "script_exec");
    Response_SHA256_Sum((const uint8_t*)hk_payload, strlen(hk_payload), h);
    Response_BytesToHex(h, 32, g->action_digest);
    snprintf(g->operator_id, sizeof(g->operator_id), "%s", op);
    g->issued_at = now;
    g->expires_at = now + 600;
    snprintf(g->nonce, sizeof(g->nonce), "00ff00ff");
    if (job) snprintf(g->job_id, sizeof(g->job_id), "%s", job);
    snprintf(g->signer_key_id, sizeof(g->signer_key_id), "%s", hk_id[k]);
    uint8_t canon[1024], sig[64];
    size_t n = EncodeGrantCanonical(g->version, g->grant_id, g->tenant_id, g->endpoint_id, g->action_kind, g->action_digest, g->operator_id,
                                    g->response_session_id, g->issued_at, g->expires_at, g->nonce, g->job_id, g->signer_key_id, canon,
                                    sizeof(canon));
    if (n == 0) n = EncodeGrantV2Canonical(2, g->grant_id, g->tenant_id, g->endpoint_id, g->action_kind, g->action_digest, g->operator_id,
                                           g->response_session_id, g->issued_at, g->expires_at, g->nonce, g->signer_key_id, canon,
                                           sizeof(canon));
    Ed25519_Sign(sig, canon, n, hk_sec[k]);
    Response_BytesToHex(sig, 64, g->signature);
}

static void test_host_authority(int64_t now) {
    (void)now;
    printf("[*] ceilings isolate and signed-scripts, host authority\n");
    make_dir();
    host_keys_setup();
    init();
    beat(FX_T0 - 4 * 86400, offer(0, FX_KEYS_JSON, FX_TB_SIG), FX_M_ENGAGEMENT_1, NULL, 0);
    expect("engagement manifest taken", T.manifest.have && strcmp(T.manifest.profile, "engagement") == 0);
    ResponseGrant g;
    memset(&g, 0, sizeof(g));
    snprintf(g.tenant_id, sizeof(g.tenant_id), "default");
    snprintf(g.action_kind, sizeof(g.action_kind), "screen_session");
    expect("screen offers are a response kind (allowed under engagement)", Trust_OfferRefusal(&T, "screen_session", &g) == NULL);

    expect("ceiling isolate accepted", Trust_SetCeiling(&T, "isolate"));
    init();
    expect("isolate: isolation, mesh, collection, updates", Trust_Allows(&T, "isolation_change") && Trust_Allows(&T, "mesh_quarantine") &&
                                                            Trust_Allows(&T, "forensic_collection") && Trust_Allows(&T, "agent_update"));
    expect("isolate: no terminal, screen or scripts", !Trust_Allows(&T, "terminal_session") && !Trust_Allows(&T, "screen_session") &&
                                                       !Trust_Allows(&T, "script_exec"));
    expect("isolate: a screen offer is refused", Trust_OfferRefusal(&T, "screen_session", &g) != NULL);

    expect("ceiling signed-scripts accepted", Trust_SetCeiling(&T, "signed-scripts"));
    init();
    expect("signed-scripts without a host key: no scripts", !Trust_Allows(&T, "script_exec") && Trust_Allows(&T, "isolation_change") &&
                                                             !Trust_Allows(&T, "terminal_session"));
    expect("ceiling monitor-signed-scripts accepted (no host key)", Trust_SetCeiling(&T, "monitor-signed-scripts"));
    init();
    expect("monitor-signed-scripts without a host key: no scripts, no isolation", !Trust_Allows(&T, "script_exec") &&
                                                                                 !Trust_Allows(&T, "isolation_change") && Trust_Allows(&T, "forensic_collection"));
    expect("ceiling signed-scripts again", Trust_SetCeiling(&T, "signed-scripts"));
    init();
    char report[4096];
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report: no host authority", strstr(report, "\"host_authority\":false") && strstr(report, "\"ceiling\":\"signed-scripts\""));

    char hf[1024];
    snprintf(hf, sizeof(hf), "{\"v\":1,\"keys\":[{\"id\":\"%s\",\"role\":\"tap\",\"ed25519\":\"", hk_id[0]);
    size_t o = strlen(hf);
    for (int i = 0; i < 32; i++) o += (size_t)snprintf(hf + o, sizeof(hf) - o, "%02x", hk_pub[0][i]);
    o += (size_t)snprintf(hf + o, sizeof(hf) - o, "\"},{\"id\":\"%s\",\"role\":\"auto\",\"ed25519\":\"", hk_id[1]);
    for (int i = 0; i < 32; i++) o += (size_t)snprintf(hf + o, sizeof(hf) - o, "%02x", hk_pub[1][i]);
    snprintf(hf + o, sizeof(hf) - o, "\"}]}");
    write_host_file("host_authority.json", hf);
    host_payload("echo scrub", "audit");
    char af[512];
    snprintf(af, sizeof(af), "{\"v\":1,\"packages\":[{\"name\":\"scrub\",\"sha256\":\"%s\",\"modes\":[\"audit\"]}]}", hk_digest);
    write_host_file("host_auto_allow.json", af);
    init();
    expect("two host keys and one allow-listed package loaded", T.host_present && T.hostKeyCount == 2 && T.hostAllowCount == 1);
    expect("signed-scripts with a host key: scripts allowed", Trust_Allows(&T, "script_exec"));
    expect("ceiling monitor-signed-scripts accepted", Trust_SetCeiling(&T, "monitor-signed-scripts"));
    init();
    expect("monitor-signed-scripts: report names the level", T.host_present && strcmp(T.ceiling, "monitor-signed-scripts") == 0);
    expect("monitor-signed-scripts with a host key: scripts, collection, updates",
           Trust_Allows(&T, "script_exec") && Trust_Allows(&T, "forensic_collection") && Trust_Allows(&T, "agent_update"));
    expect("monitor-signed-scripts: no isolation, mesh, terminal or screen",
           !Trust_Allows(&T, "isolation_change") && !Trust_Allows(&T, "mesh_quarantine") && !Trust_Allows(&T, "terminal_session") &&
               !Trust_Allows(&T, "screen_session"));
    expect("ceiling signed-scripts back", Trust_SetCeiling(&T, "signed-scripts"));
    init();
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report: host authority, key ids and roles, allow-list",
           strstr(report, "\"host_authority\":true") && strstr(report, hk_id[0]) && strstr(report, "\"role\":\"auto\"") &&
               strstr(report, "\"name\":\"scrub\"") && strstr(report, "\"modes\":[\"audit\"]"));
    expect("report is one JSON object", report[0] == '{' && report[strlen(report) - 1] == '}');
    expect("report carries the clock's UTC offset", strstr(report, "\"utc_offset_minutes\":") != NULL);

    host_grant(&g, 0, 3, "job-1", "nightshift:tap");
    expect("tap-signed V3 script grant for this job verifies", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) == NULL);
    expect("the same grant for another job is refused", Trust_OfferGrantRefusal(&T, "job-2", &g, hk_payload, FX_ENDPOINT) != NULL);
    char edited[2048];
    snprintf(edited, sizeof(edited), "%s", hk_payload);
    edited[strlen(edited) - 2] = '5';   /* max_output_bytes 4096 -> 4095 */
    expect("an edited payload is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, edited, FX_ENDPOINT) != NULL);
    expect("another endpoint is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, "ep-other") != NULL);
    host_grant(&g, 0, 2, NULL, "nightshift:tap");
    expect("a V2 grant (no job id) never runs a script here", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);
    host_grant(&g, 0, 3, "job-1", "nightshift:auto");
    expect("tap key with the auto operator is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);
    host_grant(&g, 0, 3, "job-1", "operator-secops");
    expect("an OmniNull operator on a host-key grant is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);

    host_grant(&g, 1, 3, "job-1", "nightshift:auto");
    expect("auto key: allow-listed package in an allowed mode runs", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) == NULL);
    host_payload("echo scrub", "enforce");
    host_grant(&g, 1, 3, "job-1", "nightshift:auto");
    expect("auto key: a mode not allowed is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL &&
                                                      strstr(Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT), "mode"));
    host_payload("echo other", "audit");
    host_grant(&g, 1, 3, "job-1", "nightshift:auto");
    expect("auto key: a package off the allow-list is refused",
           Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);
    host_grant(&g, 0, 3, "job-1", "nightshift:tap");
    expect("tap key: any script runs", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) == NULL);
    host_payload("echo scrub", "audit");
    {
        /* A second script_digest (an extra member the executor's string
         * search would read first) makes the payload ambiguous. */
        char amb[2200];
        snprintf(amb, sizeof(amb), "{\"x\":{\"script_digest\":\"%s\"},%s", hk_digest, hk_payload + 1);
        if (strlen(amb) < sizeof(hk_payload)) memcpy(hk_payload, amb, strlen(amb) + 1);
        host_grant(&g, 1, 3, "job-1", "nightshift:auto");
        expect("auto key: an ambiguous payload is refused", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);
        host_payload("echo scrub", "audit");
    }

    expect("a re-pin leaves the host authority alone", Trust_Repin(&T) >= 0);
    init();
    expect("host keys still loaded after the re-pin", T.hostKeyCount == 2);

    remove_host_file("host_auto_allow.json");
    init();
    host_grant(&g, 1, 3, "job-1", "nightshift:auto");
    expect("auto key without an allow-list runs nothing", Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);

    write_host_file("host_authority.json", "{\"v\":1,\"keys\":[{\"id\":\"00\",\"role\":\"tap\"}]}");
    init();
    host_grant(&g, 0, 3, "job-1", "nightshift:tap");
    expect("a malformed host file fails closed: present, no keys, scripts refused",
           T.host_present && T.hostKeyCount == 0 && !Trust_Allows(&T, "script_exec") &&
               Trust_OfferGrantRefusal(&T, "job-1", &g, hk_payload, FX_ENDPOINT) != NULL);
    Trust_ReportJSON(&T, report, sizeof(report));
    expect("report says why", strstr(report, "\"host_authority\":false") && strstr(report, "host_error"));

    {
        /* An id that is not the key's fingerprint is refused. */
        char bad[1024];
        snprintf(bad, sizeof(bad), "%s", hf);
        char* idp = strstr(bad, hk_id[0]);
        if (idp) idp[0] = idp[0] == '0' ? '1' : '0';
        write_host_file("host_authority.json", bad);
        init();
        expect("a key whose id is not its fingerprint is refused", T.hostKeyCount == 0);
    }
    remove_host_file("host_authority.json");
    Trust_SetCeiling(&T, "none");
    init();
    expect("without a host file scripts go back to the response key", !T.host_present);
    remove_dir();
}

/* ---------------------------------------------------------------------------
 * Routine release keys (routine_fixtures.h, agent/tests/gen_routine_fixtures.sh).
 * POSIX checks them with openssl; Windows with a table of the pairs the
 * fixture keys signed, or with CNG itself when built with
 * -DOMINULL_TEST_BCRYPT and -lbcrypt.
 * ------------------------------------------------------------------------- */

static uint8_t fxr_release_xy[64], fxr_a_xy[64], fxr_b_xy[64];
static Trust_KeyVerifier fxr_key_verify;

#ifdef _WIN32
#ifdef OMINULL_TEST_BCRYPT
#include "../include/release_verify_win.h"
static bool fxr_release(const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    return ReleaseVerifyWinMsg(fxr_release_xy, msg, len, der, derlen);
}
static bool fxr_key(const uint8_t* xy, const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    return ReleaseVerifyWinMsg(xy ? xy : fxr_release_xy, msg, len, der, derlen);
}
#else
static bool fxr_key(const uint8_t* xy, const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    static const struct { const char* xy; const char* msg; const char* sig; } valid[] = FXR_VALID;
    char xh[129];
    Response_BytesToHex(xy ? xy : fxr_release_xy, 64, xh);
    for (size_t i = 0; i < sizeof(valid) / sizeof(valid[0]); i++) {
        uint8_t want[160];
        size_t wl = Response_Base64Decode(valid[i].sig, strlen(valid[i].sig), want, sizeof(want));
        if (strcmp(xh, valid[i].xy) == 0 && len == strlen(valid[i].msg) && memcmp(msg, valid[i].msg, len) == 0 && derlen == wl &&
            memcmp(der, want, wl) == 0)
            return true;
    }
    return false;
}
static bool fxr_release(const char* msg, size_t len, const uint8_t* der, size_t derlen) {
    return fxr_key(NULL, msg, len, der, derlen);
}
#endif
#endif

static void init_routine(void) {
    Trust_Init(&T, FX_ENDPOINT, g_dir, g_dir, false);
#ifdef _WIN32
    T.verify_release = fxr_release;
    fxr_key_verify = fxr_key;
#else
    g_ReleaseVerifyPem = FXR_RELEASE_PEM;
    snprintf(g_ReleaseVerifyDir, sizeof(g_ReleaseVerifyDir), "%s", g_dir);
    T.verify_release = ReleaseVerifyPosix;
    fxr_key_verify = ReleaseVerifyPosixXY;
#endif
    Trust_LoadRoutine(&T);
}

static void routine_offer(int64_t now, const char* epoch, const char* keys, const char* sig) {
    /* At the top level of the heartbeat answer, as the hub sends it. */
    snprintf(resp, sizeof(resp), "{\"status\":\"ok\",\"is_isolated\":false,\"routine_keys\":{\"epoch\":%s,\"keys\":\"%s\",\"sig\":\"%s\"}}",
             epoch, keys, sig);
    T.refused[0] = '\0';
    Trust_ProcessHeartbeat(&T, resp, strlen(resp), now);
}

/* An agent update as the updaters check it: the key that verifies the
 * release statement must also verify the package. */
static bool update_ok(const char* stmtSig, const char* pkgSig, char* who, size_t cap) {
    uint8_t der[160], pder[160];
    size_t dl = Response_Base64Decode(stmtSig, strlen(stmtSig), der, sizeof(der));
    size_t pl = Response_Base64Decode(pkgSig, strlen(pkgSig), pder, sizeof(pder));
    char st[512];
    int sn = Trust_ReleaseStatement("ominull-agent_9.9.9_amd64.deb", "9.9.9",
                                    "abababababababababababababababababababababababababababababababab", st, sizeof(st));
    int signer = Trust_UpdateSigner(&T, fxr_key_verify, st, (size_t)sn, der, dl);
    if (who) Trust_SignerName(&T, signer, who, cap);
    if (signer < 0) return false;
    return fxr_key_verify(signer == 0 ? NULL : T.routine[signer - 1].xy, FXR_PKG, strlen(FXR_PKG), pder, pl);
}

static bool report_has(const char* needle) {
    static char rep[8192];
    Trust_ReportJSON(&T, rep, sizeof(rep));
    return strstr(rep, needle) != NULL;
}

static bool routine_file(const char* leaf) {
    char path[400];
    snprintf(path, sizeof(path), "%s" TRUST_SEP "%s", g_dir, leaf);
    return Trust_PathExists(path);
}

static void test_routine_keys(int64_t now) {
    printf("[*] routine release keys\n");
    Response_HexToBytes(FXR_RELEASE_XY, fxr_release_xy, 64);
    Response_HexToBytes(FXR_A_XY, fxr_a_xy, 64);
    Response_HexToBytes(FXR_B_XY, fxr_b_xy, 64);
    char st[1024];
    Trust_RoutineStatement(5, FXR_LIST_AB, st, sizeof(st));
    expect("routine-keys statement bytes", strcmp(st, FXR_STMT_5_AB) == 0);
    expect("routine-keys statement matches the Go form byte for byte", strcmp(st, FX_ROUTINE_STATEMENT) == 0);
    Trust_RoutineStatement(6, "", st, sizeof(st));
    expect("empty routine-keys statement bytes", strcmp(st, "OMINULL-ROUTINE-KEYS-V1\nepoch=6\nkeys=\n") == 0);
    char pem[200];
    expect("routine key to PEM matches openssl's", Trust_P256PEM(fxr_a_xy, pem, sizeof(pem)) && strcmp(pem, FXR_A_PEM) == 0);
    expect("release key to PEM matches openssl's", Trust_P256PEM(fxr_release_xy, pem, sizeof(pem)) && strcmp(pem, FXR_RELEASE_PEM) == 0);

    init_routine();
    expect("fresh host: no routine keys", T.routineCount == 0 && T.routine_epoch == 0);
    expect("fresh host reports routine_epoch 0 and routine_keys 0", report_has("\"routine_epoch\":0,\"routine_keys\":0"));
    char who[40];
    expect("fresh host: update signed by the release key accepted", update_ok(FXR_UPDATE_SIG_R, FXR_PKG_SIG_R, who, sizeof(who)) && strcmp(who, "main") == 0);
    expect("fresh host: update signed by a routine key refused", !update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_A, NULL, 0));

    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB_WRONG);
    expect("routine keys signed by a key other than the release key refused",
           T.routineCount == 0 && refused_with("do not verify against the release key") && !routine_file("routine.pin"));

    /* Malformed lists and fields: refused before any signature check. */
    static char bad[8][1024];
    snprintf(bad[0], sizeof(bad[0]), "%s", FXR_LIST_AB);
    for (char* c = bad[0]; *c; c++) *c = (char)toupper((unsigned char)*c);
    snprintf(bad[1], sizeof(bad[1]), "%s:%s,%s:%s", FXR_B_ID, FXR_B_XY, FXR_A_ID, FXR_A_XY);
    snprintf(bad[2], sizeof(bad[2]), "1000000000000000:%s,2000000000000000:%s,3000000000000000:%s,4000000000000000:%s,5000000000000000:%s",
             FXR_A_XY, FXR_A_XY, FXR_A_XY, FXR_A_XY, FXR_A_XY);
    snprintf(bad[3], sizeof(bad[3]), "111111111111111:%s", FXR_A_XY);
    snprintf(bad[4], sizeof(bad[4]), "%s:%s, %s:%s", FXR_A_ID, FXR_A_XY, FXR_B_ID, FXR_B_XY);
    snprintf(bad[5], sizeof(bad[5]), "%s,", FXR_LIST_A);
    snprintf(bad[6], sizeof(bad[6]), "%s:%s,%s:%s", FXR_A_ID, FXR_A_XY, FXR_A_ID, FXR_B_XY);
    snprintf(bad[7], sizeof(bad[7]), "%s:%.126s", FXR_A_ID, FXR_A_XY);
    const char* why[8] = {"uppercase hex", "unsorted ids", "five keys", "short id", "a space", "a trailing comma", "a repeated id", "short point"};
    for (int i = 0; i < 8; i++) {
        TrustRoutineKey k[TRUST_MAX_ROUTINE_KEYS];
        int n = 0;
        char what[96];
        snprintf(what, sizeof(what), "routine key list with %s refused", why[i]);
        routine_offer(now, "5", bad[i], FXR_SIG_5_AB);
        expect(what, !Trust_ParseRoutineList(bad[i], k, &n) && T.routineCount == 0 && refused_with("malformed"));
    }
    {
        TrustRoutineKey k[TRUST_MAX_ROUTINE_KEYS];
        int n = -1;
        expect("an empty list parses as no keys", Trust_ParseRoutineList("", k, &n) && n == 0);
        expect("four sorted keys parse", Trust_ParseRoutineList(FXR_LIST_AB, k, &n) && n == 2 && strcmp(k[1].id, FXR_B_ID) == 0 &&
                                             memcmp(k[0].xy, fxr_a_xy, 64) == 0);
    }
    const char* badEpoch[] = {"0", "-5", "5.0", "5e0", "\"5\"", "05", "null"};
    for (size_t i = 0; i < sizeof(badEpoch) / sizeof(badEpoch[0]); i++) {
        char what[96];
        snprintf(what, sizeof(what), "routine epoch %s refused", badEpoch[i]);
        routine_offer(now, badEpoch[i], FXR_LIST_AB, FXR_SIG_5_AB);
        expect(what, T.routineCount == 0 && refused_with("malformed"));
    }
    routine_offer(now, "5", FXR_LIST_AB, "");
    expect("routine keys without a signature refused", T.routineCount == 0 && refused_with("malformed"));

    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB);
    expect("release-signed routine keys pinned", T.routineCount == 2 && T.routine_epoch == 5 && !refused_with("routine") &&
                                                     routine_file("routine.pin") && routine_file("routine.epoch"));
    expect("report carries routine_epoch 5 and routine_keys 2", report_has("\"routine_epoch\":5,\"routine_keys\":2"));
    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB);
    expect("the same epoch and keys again is a no-op", T.routineCount == 2 && T.routine_epoch == 5 && !refused_with("routine"));
    routine_offer(now, "5", FXR_LIST_A, FXR_SIG_5_A);
    expect("the same epoch with other keys refused", T.routineCount == 2 && refused_with("older than the set pinned"));
    routine_offer(now, "4", FXR_LIST_A, FXR_SIG_4_A);
    expect("a lower epoch refused", T.routineCount == 2 && T.routine_epoch == 5 && refused_with("older than the set pinned"));
    routine_offer(now, "7", FXR_LIST_AB, FXR_SIG_7_AB_BY_A);
    expect("a routine key cannot sign routine keys", T.routine_epoch == 5 && refused_with("do not verify against the release key"));

    init_routine();
    expect("routine keys reload and re-verify at start", T.routineCount == 2 && T.routine_epoch == 5 && strcmp(T.routine[0].id, FXR_A_ID) == 0);
    expect("update statement signed by a routine key accepted", update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_A, who, sizeof(who)) &&
                                                                    strcmp(who, "routine:" FXR_A_ID) == 0);
    expect("routine-signed statement with a package signed by another routine key refused", !update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_B, NULL, 0));
    expect("routine-signed statement with a package signed by the release key refused", !update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_R, NULL, 0));
    expect("release-signed statement with a routine-signed package refused", !update_ok(FXR_UPDATE_SIG_R, FXR_PKG_SIG_A, NULL, 0));
    expect("release-signed update still accepted", update_ok(FXR_UPDATE_SIG_R, FXR_PKG_SIG_R, who, sizeof(who)) && strcmp(who, "main") == 0);
    expect("update statement signed by neither refused", !update_ok(FXR_UPDATE_SIG_W, FXR_PKG_SIG_R, NULL, 0));

    /* A routine key never stands in for the release key anywhere else. */
    beat(now, offer(0, FX_KEYS_JSON, FXR_TB_SIG_BY_A), NULL, NULL, 0);
    expect("a routine key never verifies a trust bundle", !T.have_key[0] && !T.have_key[1] && !T.have_key[2] && refused_with("does not verify"));
    {
        uint8_t der[160];
        size_t dl = Response_Base64Decode(FXR_TB_SIG_BY_A, strlen(FXR_TB_SIG_BY_A), der, sizeof(der));
        expect("the release verifier refuses a routine key's signature", !T.verify_release(FX_TB_STATEMENT, strlen(FX_TB_STATEMENT), der, dl));
        dl = Response_Base64Decode(FXR_UPDATE_SIG_A, strlen(FXR_UPDATE_SIG_A), der, sizeof(der));
        expect("the release verifier refuses a routine-signed release statement", !T.verify_release(FXR_UPDATE_STMT, strlen(FXR_UPDATE_STMT), der, dl));
    }

    /* A changed pin is ignored and reported; the set in force can be sent again. */
    char path[400], buf[2048];
    snprintf(path, sizeof(path), "%s" TRUST_SEP "routine.pin", g_dir);
    FILE* f = fopen(path, "rb");
    size_t n = f ? fread(buf, 1, sizeof(buf) - 1, f) : 0;
    if (f) fclose(f);
    buf[n] = '\0';
    char* e = strstr(buf, "epoch=5");
    if (e) e[6] = '9';
    f = fopen(path, "wb");
    if (f) {
        fputs(buf, f);
        fclose(f);
    }
    init_routine();
    expect("a tampered routine.pin is ignored and reported", T.routineCount == 0 && T.routine_epoch == 0 && refused_with("routine.pin does not verify"));
    expect("with the pin ignored a routine-signed update is refused", !update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_A, NULL, 0));
    routine_offer(now, "4", FXR_LIST_A, FXR_SIG_4_A);
    expect("the floor still refuses a lower epoch", T.routineCount == 0 && refused_with("older"));
    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB);
    expect("the set in force is pinned again", T.routineCount == 2 && T.routine_epoch == 5);
    Trust_RemoveFile(path);
    init_routine();
    expect("without routine.pin no routine key", T.routineCount == 0 && T.routine_floor == 5);
    routine_offer(now, "4", FXR_LIST_A, FXR_SIG_4_A);
    expect("the floor survives a removed routine.pin", T.routineCount == 0 && refused_with("older"));
    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB);
    expect("restored", T.routineCount == 2);

    /* An empty list revokes every routine key. */
    routine_offer(now, "6", "", FXR_SIG_6_NONE);
    expect("an empty list revokes the routine keys", T.routineCount == 0 && T.routine_epoch == 6 && !refused_with("routine"));
    expect("report after revocation", report_has("\"routine_epoch\":6,\"routine_keys\":0"));
    expect("an update signed by a revoked routine key is refused", !update_ok(FXR_UPDATE_SIG_A, FXR_PKG_SIG_A, NULL, 0));
    init_routine();
    expect("the revocation holds after a restart", T.routineCount == 0 && T.routine_epoch == 6 && !refused_with("routine"));
    routine_offer(now, "5", FXR_LIST_AB, FXR_SIG_5_AB);
    expect("the revoked set cannot be sent again", T.routineCount == 0 && refused_with("older"));
    expect("after revocation the release key still signs updates", update_ok(FXR_UPDATE_SIG_R, FXR_PKG_SIG_R, NULL, 0));
}

int main(void) {
    int64_t now = FX_T0 + 100;
    test_versions();
    test_ip();
    make_dir();
    test_pinning_and_bootstrap(now);
    test_manifest(now);
    test_grants(now);
    remove_dir();
    test_monitor_release(now);
    test_offers_and_updates(now);
    test_host_authority(now);
    make_dir();
    test_routine_keys(now);
    remove_dir();
    if (failures) {
        printf("[-] agent trust: %d failure(s)\n", failures);
        return 1;
    }
    printf("[+] agent trust: all checks passed\n");
    return 0;
}
